//! 🧪️ Actual primitive collection owners must respect the original item and metadata-copy grants.
use semio_framework_value_retirement::{RetireOwned,RetainedCloneGrant,RetainedCloneProgress,RetainedAllocationEffect,retirement::{RetirementCursor,RetirementStep}};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
use semio_framework_value_control_contract::*;
use semio_framework_value_retirement::OriginalRetirementFailure;
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
struct Close;
impl OriginalEffectProducer for Close{type Output=RetirementStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=(usize,&'a mut dyn RetirementCursor) where 'b:'a;fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{Ok(())}fn source_turn<'a,'b>(&self,_:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{None}fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,RetirementStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetirementStep,OriginalRetirementFailure>,ValueError>where 'b:'a{c.1.close_into(c.0,e,r)}fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,RetirementStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetirementStep,OriginalRetirementFailure>,ValueError>where 'b:'a{c.1.recover_close_into(c.0,e,r)}}
fn drive<C:RetirementCursor>(cursor:&mut C,bank:&mut EffectBank,body:usize,g:RetainedCloneGrant,work:u64)->(RetirementStep,(usize,usize)){let mut authority=OriginalEffectAuthority::new(Close);let(mut action,mut reply)=(None,None);let((poll,actual),heap)=observe(||bank.run(g,work,|effect|{let before=effect.performed_work();let mut c=(body,cursor as &mut dyn RetirementCursor);assert!(authority.drive(&mut c,effect,&mut action).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work:effect.performed_work()-before})}));assert_eq!(actual,None);let RetainedWorkPoll::Complete(turn)=poll else{panic!("native collection leaf stayed pending")};turn.result.unwrap();assert!(action.as_mut().unwrap().transfer_reply(&mut reply).unwrap());authority.finish(&mut action).unwrap();let step=reply.unwrap().unwrap();let p=match &step{RetirementStep::Progress(p,_)=>*p,_=>Default::default()};assert_eq!(bank.take_admitted(),if turn.work==0{None}else{Some(true)});bank.post(p,g,heap);assert!(authority.into_producer().is_ok());(step,heap)}
fn progress(step:RetirementStep)->(RetainedCloneProgress,u128){match step{RetirementStep::Progress(p,w)=>(p,w),RetirementStep::Bytes(bytes)=>(RetainedCloneProgress{copied_items:1,released_bytes:bytes,..Default::default()},1),RetirementStep::Complete(w)=>(Default::default(),w),RetirementStep::BudgetExhausted=>(Default::default(),0),RetirementStep::Failure(error,_)=>panic!("actual scalar collection refused: {error}"),_=>panic!("primitive collection must not fabricate child cursor births")}}
fn exercise<C:RetirementCursor>(mut cursor:C,pointer:*const u8,header:usize,initial:(usize,usize),f:&serde_json::Value){
 let body=f["body"].as_u64().unwrap()as usize;let units=f["maximumWork"].as_u64().unwrap();let mut bank=EffectBank::new(Wallet::new(RetainedCloneGrant{maximum_items:256,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:32},256));for row in f["minimumQuotes"].as_array().unwrap(){let d=cursor.next_demand(row["body"].as_u64().unwrap()as usize).unwrap();assert_eq!(d.copy_bytes,row["copyBytes"].as_u64().unwrap()as usize);assert_eq!(cursor.next_demand(d.copy_bytes).unwrap(),d)}
 let selected=f["selectedBodyDenial"].as_object().unwrap();let selected_body=selected["body"].as_u64().unwrap()as usize;let d=cursor.next_demand(selected_body).unwrap();assert_eq!(d.copy_bytes,selected["selectedCopy"].as_u64().unwrap()as usize);let denied=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:selected["physicalCopy"].as_u64().unwrap()as usize,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let(step,heap)=drive(&mut cursor,&mut bank,selected_body,denied,units);assert_eq!(progress(step),(Default::default(),u128::from(selected["performedWork"].as_u64().unwrap())));assert_eq!(heap,(0,0));assert_eq!(cursor.next_demand(selected_body).unwrap(),d);
 for expected in f["remaining"].as_array().unwrap(){let d=cursor.next_demand(body).unwrap();let g=RetainedCloneGrant{maximum_items:f["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};for (items,work) in [(0,units),(g.maximum_items,0)]{let denied=RetainedCloneGrant{maximum_items:items,..g};let(step,heap)=drive(&mut cursor,&mut bank,body,denied,work);assert_eq!(heap,(0,0));assert_eq!(progress(step),(Default::default(),0));assert_eq!(cursor.next_demand(body).unwrap(),d)}
 let(step,heap)=drive(&mut cursor,&mut bank,body,g,units);let(p,w)=progress(step);assert!(p.fits(g),"real primitive retirement must retain its original item grant: {p:?} {g:?}");assert_eq!(p.copied_items,1);assert_eq!(w,u128::from(units));assert_eq!(heap,(0,0));assert_eq!(unsafe{std::slice::from_raw_parts(pointer,3)},[11,23,37]);let left=expected.as_u64().unwrap()as usize;let next=cursor.next_demand(body).unwrap();if left!=0{assert_eq!(next.copy_bytes,std::mem::size_of::<usize>()+left)}else{assert_eq!(next.copy_bytes,header)}
 }
 let d=cursor.next_demand(body).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let denied=RetainedCloneGrant{maximum_copy_bytes:header-1,..g};let(step,heap)=drive(&mut cursor,&mut bank,body,denied,units);assert_eq!(progress(step),(Default::default(),0));assert_eq!(heap,(0,0));assert!(!cursor.terminal_is_empty());assert_eq!(cursor.next_demand(body).unwrap(),d);
 let(step,heap)=drive(&mut cursor,&mut bank,body,g,units);let(p,w)=progress(step);assert_eq!(p.copied_items,f["releaseItems"].as_u64().unwrap()as usize);assert_eq!(p.copied_bytes,header);assert_eq!(w,u128::from(units));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert_eq!(initial.0,initial.1+heap.1);assert!(cursor.terminal_is_empty());let(step,heap)=drive(&mut cursor,&mut bank,body,Default::default(),0);assert_eq!(progress(step),(Default::default(),0));assert_eq!(heap,(0,0));assert_eq!(observe(||drop(cursor)).1,(0,0));
}
#[test]
fn scalar_vector_and_deque_keep_each_original_item_and_header_clear_grant(){
 let f:serde_json::Value=serde_json::from_str(include_str!("cases.json")).unwrap();let(_,probe)=observe(||{let p=std::hint::black_box(Vec::<u8>::with_capacity(73));std::hint::black_box(p.as_ptr());drop(p)});assert_eq!(probe,(73,73));
 for owner in f["owners"].as_array().unwrap(){let(input,initial)=observe(||f["values"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u8).collect::<Vec<_>>());if owner=="vector"{let pointer=input.as_ptr();let(cursor,heap)=observe(||input.retirement_seed());assert_eq!(heap,(0,0));exercise(cursor,pointer,std::mem::size_of::<Vec<u8>>(),initial,&f)}else{let deque:std::collections::VecDeque<_>=input.into();let pointer=deque.as_slices().0.as_ptr();let(cursor,heap)=observe(||deque.retirement_seed());assert_eq!(heap,(0,0));exercise(cursor,pointer,std::mem::size_of::<std::collections::VecDeque<u8>>(),initial,&f)}}
}

#[test]
fn fixed_array_preserves_its_selected_body_under_short_physical_copy(){
 let f:serde_json::Value=serde_json::from_str(include_str!("cases.json")).unwrap();let row=&f["fixedArray"];let body=row["body"].as_u64().unwrap()as usize;let mut cursor=[11u8,23,37].retirement_seed();let mut bank=EffectBank::new(Wallet::new(RetainedCloneGrant{maximum_items:32,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:32},64));let d=cursor.next_demand(body).unwrap();assert_eq!(d.copy_bytes,row["selectedCopy"].as_u64().unwrap()as usize);let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:row["physicalCopy"].as_u64().unwrap()as usize,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let(step,heap)=drive(&mut cursor,&mut bank,body,grant,1);assert_eq!(progress(step),(Default::default(),u128::from(row["performedWork"].as_u64().unwrap())));assert_eq!(heap,(0,0));assert_eq!(cursor.next_demand(body).unwrap(),d);
 for remaining in (0..3).rev(){let d=cursor.next_demand(body).unwrap();let grant=RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes,..grant};let(step,heap)=drive(&mut cursor,&mut bank,body,grant,1);assert_eq!(progress(step),(RetainedCloneProgress{copied_items:1,copied_bytes:row["slotBytes"].as_u64().unwrap()as usize+row["headerBytes"].as_u64().unwrap()as usize,..Default::default()},1));assert_eq!(heap,(0,0));if remaining==0{assert!(cursor.terminal_is_empty())}else{assert_eq!(cursor.next_demand(body).unwrap().copy_bytes,remaining*row["slotBytes"].as_u64().unwrap()as usize+row["headerBytes"].as_u64().unwrap()as usize)}}
 assert_eq!(observe(||drop(cursor)).1,(0,0));
}

static BODY_CALLS:std::sync::atomic::AtomicUsize=std::sync::atomic::AtomicUsize::new(0);
static BODY_RECOVERIES:std::sync::atomic::AtomicUsize=std::sync::atomic::AtomicUsize::new(0);
struct BodyOwner;
struct BodyCursor{phase:u8}
impl RetireOwned for BodyOwner{type RetirementCursor=BodyCursor;fn retirement_seed(self)->BodyCursor{BodyCursor{phase:0}}fn controlled_retirement_supported()->bool{true}}
impl RetirementCursor for BodyCursor{
 fn next_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{Ok(if self.phase==2{Default::default()}else{RetirementDemand{copy_bytes:8+body.min(4),depth:1,..Default::default()}})}
 fn next_computational_work(&self,_:usize)->Result<u64,ValueError>{Ok(if self.phase==2{0}else{2})}
 fn terminal_is_empty(&self)->bool{self.phase==2}
 fn terminal_release_bytes(&self)->Option<usize>{self.terminal_is_empty().then_some(std::mem::size_of::<Self>())}
 fn close_into<'r>(&mut self,body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetirementStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetirementStep,OriginalRetirementFailure>,ValueError>{assert_eq!(body,64);assert_eq!(self.phase,0);assert_eq!(effect.maximum_work_units(),2);assert_eq!(effect.grant().maximum_copy_bytes,12);assert!(effect.performed(1)?);self.phase=1;BODY_CALLS.fetch_add(1,std::sync::atomic::Ordering::Relaxed);Ok(reply.pending())}
 fn recover_close_into<'r>(&mut self,body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetirementStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetirementStep,OriginalRetirementFailure>,ValueError>{assert_eq!(body,64);assert_eq!(self.phase,1);assert_eq!(effect.maximum_work_units(),1);assert!(effect.performed(1)?);self.phase=2;BODY_RECOVERIES.fetch_add(1,std::sync::atomic::Ordering::Relaxed);Ok(reply.complete(Ok(RetirementStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:12,..Default::default()},1))))}
}
impl Drop for BodyCursor{fn drop(&mut self){assert!(self.phase==2)}}
struct ControlledClose;
impl OriginalEffectProducer for ControlledClose{
 type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=(usize,&'a mut semio_framework_value_retirement::retirement::controlled::ControlledRetirement<BodyOwner>) where 'b:'a;
 fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{Ok(())}
 fn source_turn<'a,'b>(&self,_:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{None}
 fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{c.1.step_into(c.0,e,r)}
 fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{c.1.recover_step_into(c.0,e,r)}
}
#[test]
fn controlled_child_keeps_body_and_remaining_work_across_pending(){
 let f:serde_json::Value=serde_json::from_str(include_str!("cases.json")).unwrap();let row=&f["controlledPending"];let body=row["body"].as_u64().unwrap()as usize;let mut owner=semio_framework_value_retirement::retirement::controlled::ControlledRetirement::retain(BodyOwner);let mut bank=EffectBank::new(Wallet::new(RetainedCloneGrant{maximum_items:128,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:32},1024));let mut authority=OriginalEffectAuthority::new(ControlledClose);let(mut action,mut answer)=(None,None);let mut total=(0usize,0usize);BODY_CALLS.store(0,std::sync::atomic::Ordering::Relaxed);BODY_RECOVERIES.store(0,std::sync::atomic::Ordering::Relaxed);
 assert_eq!(owner.next_depth_demand().unwrap(),row["initialSelectedDepth"].as_u64().unwrap()as usize);for _ in 0..128{if owner.terminal_is_empty(){break}let d=owner.next_demand(body).unwrap();assert_eq!(owner.next_depth_demand().unwrap(),d.depth);let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let denied=RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..grant};let((poll,marker),heap)=observe(||bank.run(denied,row["parentWork"].as_u64().unwrap(),|effect|{let mut c=(body,&mut owner);assert!(authority.drive(&mut c,effect,&mut action).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work:effect.performed_work()})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("denied native depth stayed pending")};assert_eq!(turn.work,0);turn.result.unwrap();assert_eq!(marker,None);assert_eq!(heap,(0,0));assert!(action.as_mut().unwrap().transfer_reply(&mut answer).unwrap());authority.finish(&mut action).unwrap();assert_eq!(answer.take().unwrap().unwrap().progress(),Default::default());assert_eq!(bank.take_admitted(),None);bank.post(Default::default(),denied,heap);assert_eq!(owner.next_demand(body).unwrap(),d);let mut action_heap=(0usize,0usize);loop{let((poll,marker),heap)=observe(||bank.run(grant,row["parentWork"].as_u64().unwrap(),|effect|{let before=effect.performed_boundary();let mut c=(body,&mut owner);let done=authority.drive(&mut c,effect,&mut action).unwrap();let work=effect.performed_since(before).unwrap();if done{RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work})}else{RetainedWorkPoll::Pending{work}}}));action_heap.0+=heap.0;action_heap.1+=heap.1;if let Some(marker)=marker{assert_eq!(marker,action_heap.0)}let RetainedWorkPoll::Complete(turn)=poll else{assert!(owner.next_demand(body+1).is_err());assert!(owner.next_computational_work(body+1).is_err());assert_eq!(owner.next_demand(body).unwrap(),d);assert_eq!(owner.next_depth_demand().unwrap(),d.depth);assert_eq!(owner.next_release_byte_demand().unwrap(),d.release_bytes);assert_eq!(BODY_CALLS.load(std::sync::atomic::Ordering::Relaxed),1);assert_eq!(BODY_RECOVERIES.load(std::sync::atomic::Ordering::Relaxed),0);continue};turn.result.unwrap();assert!(action.as_mut().unwrap().transfer_reply(&mut answer).unwrap());authority.finish(&mut action).unwrap();let step=answer.take().unwrap().unwrap();assert_ne!(bank.take_admitted(),Some(false));bank.post(step.progress(),grant,action_heap);total.0+=action_heap.0;total.1+=action_heap.1;break}}
 assert!(owner.terminal_is_empty());assert_eq!(BODY_CALLS.load(std::sync::atomic::Ordering::Relaxed),row["calls"].as_u64().unwrap()as usize);assert_eq!(BODY_RECOVERIES.load(std::sync::atomic::Ordering::Relaxed),row["recoveries"].as_u64().unwrap()as usize);assert_eq!(total.0,total.1);assert_eq!(observe(||drop(owner)).1,(0,0));assert!(authority.into_producer().is_ok());
}
